#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 1000000007;

int add_mod(int a, int b) {
    int res = a + b;
    if (res >= MOD) res -= MOD;
    return res;
}

int getMax(const vector<vector<vector<int>>> &dp, int i, int j, bool start, bool end) {
    int res = 0;
    if (i - j >= 2) {
        if (start) {
            res = add_mod(res, add_mod(dp[i - 1][j + 1][1], 1));
        } else {
            res = add_mod(res, dp[i - 1][j + 1][0]);
        }
    }
    if (j > 0) {
        if (end) {
            res = add_mod(res, add_mod(dp[i - 1][j - 1][1], 1));
        } else {
            res = add_mod(res, dp[i - 1][j - 1][0]);
        }
    }
    return res;
}

int compute(int n) {
    int total = 2 * n;
    vector<vector<vector<int>>> dp(total + 1, vector<vector<int>>(total + 1, vector<int>(2, 0)));
    for (int i = 1; i <= total; i++) {
        for (int j = 0; j <= i; j++) {
            for (int k = 0; k <= 1; k++) {
                if (k == 1) {
                    if (i - j >= 2) {
                        dp[i][j][k] = add_mod(dp[i][j][k], dp[i - 1][j + 1][0]);
                    }
                    if (j > 0) {
                        dp[i][j][k] = add_mod(dp[i][j][k], dp[i - 1][j - 1][0]);
                    }
                } else {
                    int val1 = getMax(dp, i, j, false, false);
                    int val2 = getMax(dp, i, j, false, true);
                    int val3 = getMax(dp, i, j, true, false);
                    dp[i][j][k] = max(val1, max(val2, val3));
                }
            }
        }
    }
    return dp[total][0][0];
}

int main() {
    int n;
    cin >> n;
    int answer = compute(n);
    cout << answer;
    return 0;
}

